# -*- coding: utf-8 -*-
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'dd29'))
from fams import *
F = 'user'
REFUND = ('What if the username claim does not work?', 'If a username claim fails, you get a full 100% refund. A claim fails when the username is not successfully claimed onto your profile. Details are on the refund policy page.')
def u(slug, title, h1, crumb, desc, hero, answer, cards, secs, faq, who, **kw):
    page(slug, F, title, desc, h1, crumb, hero, answer, cards, secs, faq + [REFUND], who, **kw)
RULES = 'Every claim goes through the platform’s own processes. No bots, no false reports, no buying or selling accounts.'

u('instagram-username-claim-for-real-estate-agents', 'Instagram Username Claim for Real Estate Agents',
 'Want the Instagram username that matches your agency name?', 'Username claim for real estate agents',
 'Real estate agents and agencies that want the Instagram handle matching their name: what proof helps, who usually holds it and what to send.',
 'Buyers and sellers search by agent and agency name. If your handle is taken, here is what to check first.',
 'Agent and agency handles are often held by a former colleague, a franchise office or an old listing account. Check whether the holder is active, whether it uses your name or logo, and what you can show: a licence, an agency registration, listing pages and signage. Those facts decide which official route fits.',
 [('Check the holder', 'A former colleague, a franchise page and a copycat each need a different route.'),
  ('Show your licence', 'A real estate licence or agency registration ties the name to you.'),
  ('Keep listings consistent', 'Your website and listings should show the same name as the handle you want.')],
 [S('Who tends to hold an agent handle', ul(['A former agent from the same office who used the name.', 'A franchise or network page that registered it first.', 'An abandoned account made when you first set up.', 'A copycat that posts listings under your name.']), RULES),
  S('What to send', ol(['The handle you want and the one you use now.', 'Your licence number or agency registration.', 'A screenshot of the holder’s profile and latest post.', 'A line on why the name is yours.']))],
 [('Does a franchise name complicate this?', 'It can. The franchise may hold rights to the brand part of the name. Tell us how the name is used.'),
  ('Can I claim a handle used by a former colleague?', 'If the account is active and genuine, usually not. If it uses your name to mislead, a report may apply.'),
  ('Is a licence number required?', 'It is not required, but it is strong proof that the name is yours.')],
 ['Independent agents building a personal brand.', 'Small agencies and brokerages.', 'Property managers and developers.'])

u('instagram-username-claim-for-salons-and-barbers', 'Instagram Username Claim for Salons and Barbers',
 'Want the Instagram username that matches your salon name?', 'Username claim for salons and barbers',
 'Salons, barbershops and studios that want the Instagram handle matching their name: when a claim fits, what proof helps and what to send.',
 'Clients book by looking for your shop name. If someone else holds the handle, here is how it works.',
 'Salon and barbershop handles are often held by a previous owner, a stylist who left or a booking-page account. Check whether it is active, whether it uses your shop name or signage, and what you can show: a business registration, a lease, a booking page and photos of the shop front. Those details decide which route fits.',
 [('Who opened it first', 'A previous owner and a stylist who left are different from a stranger.'),
  ('Use your shop records', 'Registration, lease and signage show the name belongs to your business.'),
  ('Do not pay for the handle', 'Buying a handle breaks the platform rules and risks your account.')],
 [S('Common situations', ul(['The old owner kept the account when the shop changed hands.', 'A stylist registered the name for themselves.', 'A booking site created a page under the shop name.', 'An unrelated shop in another city uses the same word.']), RULES),
  S('What to send', ol(['The handle you want and your current handle.', 'Your business registration or lease.', 'A photo of the shop front showing the name.', 'Screenshots of the holder’s profile.']))],
 [('The old owner has the account. Can I get it?', 'It depends on the facts and the proof of who owns the business name. We tell you honestly what is realistic.'),
  ('What if a stylist registered it?', 'A stylist using the shop name for personal work is treated differently from one posing as the shop.'),
  ('Can I use a different handle in the meantime?', 'Yes. A close variation lets clients find you while the claim is checked.')],
 ['Salon and barbershop owners.', 'Nail, brow and beauty studios.', 'Stylists who rent a chair under a shop name.'])

u('instagram-username-claim-for-ecommerce-brands', 'Instagram Username Claim for Ecommerce Brands',
 'Want the Instagram username that matches your store name?', 'Username claim for ecommerce brands',
 'Online stores that want the Instagram handle matching their brand: how a domain and trademark support a claim, and what to send.',
 'Shoppers look for your store by name. If the handle is taken, the proof you hold matters more than the history.',
 'Ecommerce brands often find the handle held by a dropshipper, a reseller or a fan account. A domain registered earlier, a store with real orders and a trademark filing all show the name is yours. Check what the holder posts, then pick the route: a brand report, an impersonation report or the inactive account route.',
 [('Show the domain date', 'A domain registered before the account strengthens a brand report.'),
  ('Find out what they sell', 'A reseller, a copycat and a fan page are treated differently.'),
  ('Protect the name', 'A trademark filing adds weight where it applies.')],
 [S('What strengthens a claim', ul(['A domain registered before the account was created.', 'A live store with orders under the name.', 'A trademark filing in the countries you sell to.', 'Evidence that shoppers confuse the two accounts.']), RULES),
  S('What to send', ol(['The handle you want and your current handle.', 'Your store link and domain registration date.', 'Trademark details, if any.', 'Screenshots of the holder’s profile and posts.']))],
 [('Does a Shopify or Etsy store count?', 'Yes. A live store with real activity is evidence of use of the name.'),
  ('What if a reseller uses my brand?', 'Selling your products under your name without permission can support a brand report.'),
  ('Do I need a trademark?', 'Not for every route, but it helps where the holder is copying your brand.')],
 ['Direct-to-consumer brands.', 'Shopify, Etsy and Amazon sellers.', 'Founders who grew the store before the handle.'])

u('instagram-username-claim-for-coaches-and-consultants', 'Instagram Username Claim for Coaches and Consultants',
 'Want the Instagram username that matches your name or practice?', 'Username claim for coaches and consultants',
 'Coaches and consultants that want the Instagram handle matching their name or practice: what proof helps, who holds it and what to send.',
 'For a coach, the handle is the business card. If someone else holds it, here is what is worth checking.',
 'Coaches and consultants usually want their own name or practice name as the handle. It is often held by a namesake, an old account of yours or a fan page. Check whether the holder is active, where your name appears online, and what records you have: a registered practice, a website and published work. Those facts decide the route.',
 [('Are they a namesake', 'A real person with the same name keeps the handle in most situations.'),
  ('Look for your old account', 'An account you opened years ago can often be recovered instead.'),
  ('Gather public proof', 'Your website, books or talks show the name is tied to you.')],
 [S('What decides the route', ul(['The holder is a genuine namesake with an active account.', 'The holder is empty or inactive for a long time.', 'The account copies your brand or photos.', 'The account is an old one of yours you can no longer access.']), RULES),
  S('What to send', ol(['The handle you want and your current profile.', 'Your website or practice registration.', 'Where your name is published online.', 'Screenshots of the holder’s profile.']))],
 [('Can I claim my own name from a namesake?', 'Usually not. An active account of a real person with the same name is not claimable.'),
  ('What if it is my old account?', 'Then recovery of that account may be the right route instead of a claim.'),
  ('Do I need to be verified?', 'No. Verification helps show who is official but is not required.')],
 ['Life, business and career coaches.', 'Independent consultants.', 'Trainers and speakers.'])

u('instagram-username-claim-for-professional-firms', 'Instagram Username Claim for Law and Accounting Firms',
 'Want the Instagram username that matches your firm name?', 'Username claim for professional firms',
 'Law, accounting and advisory firms that want the Instagram handle matching their name: what registrations help and what to send.',
 'Professional firms are searched by name. If the handle is held by someone else, the firm records carry the weight.',
 'Law, accounting and advisory firms often find the firm name held by a former colleague, a directory page or a similar firm elsewhere. A firm registration, a regulator listing and a trademark filing show the name belongs to you. Check what the holder posts and whether it suggests an affiliation with your firm that does not exist.',
 [('Use regulator records', 'A bar or accounting body listing ties the name to your firm.'),
  ('Check for false affiliation', 'An account implying it is your firm may support an impersonation report.'),
  ('Agree who acts for the firm', 'A former colleague may have a say. Agree who acts for the firm first.')],
 [S('Records that matter here', ul(['The firm registration with the date.', 'A regulator or professional body listing.', 'A trademark filing for the firm name.', 'A website that has used the name for some time.']), RULES),
  S('What to send', ol(['The handle you want and your current handle.', 'Firm registration and any regulator listing.', 'Screenshots of the holder’s profile.', 'A line on who is authorised to act for the firm.']))],
 [('Can a former colleague hold the handle?', 'They can, if they opened it. If it uses the firm name to mislead, a report may apply.'),
  ('Does a firm directory page count?', 'A directory page is usually a third-party listing. Its handle may be claimable if inactive.'),
  ('Is this legal advice?', 'No. For trademark questions, speak to a qualified professional.')],
 ['Law firms and solicitors.', 'Accountants and tax advisers.', 'Financial planners and consultancies.'])

