u('instagram-username-held-by-a-deactivated-account', 'Instagram Username Held by a Deactivated Account',
 'A deactivated Instagram account holds the username you want?', 'Username held by a deactivated account',
 'A deactivated account holds the Instagram username you want? How it differs from deleted and inactive accounts and what can be done.',
 'A deactivated account can look empty but still keep the name. The difference from deleted matters.',
 'When someone deactivates an Instagram account, the profile is hidden but the username stays reserved for them. That is different from a deleted account, where the name is later released, and from an inactive but live account. A hidden profile usually cannot be claimed while the owner can still return. We tell you honestly what is realistic.',
 [('Deactivated is not deleted', 'The owner can come back, and the name stays reserved.'),
  ('Check the signs', 'No profile found, but the name shows as taken, often means deactivated.'),
  ('Waiting can be the answer', 'Names of deleted accounts return to the pool later.')],
 [S('How the three states differ', ul(['Deactivated: hidden profile, name reserved, owner can return.', 'Deleted: profile removed, the name is released after a while.', 'Inactive: profile visible and untouched for a long time.', 'Suspended: the platform disabled it, which is a different process.']), RULES),
  S('What to send', ol(['The username you want.', 'What you see when you search for it.', 'Whether you know the former owner.', 'Your current profile and why the name is yours.']))],
 [('Can a deactivated username be claimed?', 'Usually not while the owner can reactivate. A strong brand claim may still be looked at.'),
  ('How do I know if it is deactivated?', 'The profile does not load, yet you cannot register the name.'),
  ('Can I ask the owner to release it?', 'You can, if you know them. Do not pay for it, as buying a handle breaks the rules.')],
 ['People who see the name as taken but find no profile.', 'Brands whose old handle went quiet.', 'Anyone unsure if a name is held.'])

u('instagram-username-claim-ireland', 'Instagram Username Claim in Ireland',
 'Want an Instagram username in Ireland?', 'Username claim in Ireland',
 'Irish business or creator whose name is held on Instagram by someone else? What a CRO entry and an EU mark add, and what to send.',
 'An Irish trading name and the Instagram handle you want are not always the same. Here is how that plays out.',
 'In Ireland, a trading name can differ from the registered company name, and a third party may hold the matching handle. A CRO entry or a business name registration shows the name and its start date, and an EU trademark covers the whole union. Send them with the holder’s profile and we say if a claim is realistic.',
 [('Match the registered name', 'The CRO or business name entry should show the word in the handle you want.'),
  ('An EU mark covers Ireland', 'It supports a brand report more than a trading name alone.'),
  ('Check the holder', 'An empty account and a copycat are handled differently.')],
 [S('What the Irish records show', ul(['A CRO company or business name entry with the date.', 'An EUIPO or Irish trademark, if filed.', 'A website or invoices carrying the name.', 'Whether the holder sells under your name.']), RULES),
  S('Sending your details', ol(['The handle you want and the one you run today.', 'Your CRO entry or business name registration.', 'A screenshot of the holder’s profile.', 'A short line on why the name is yours.']))],
 [('Do you only work with Irish clients?', 'No. Unbanz works with clients worldwide, and you can write in English.'),
  ('Is a CRO entry enough?', 'It supports a claim but is not decisive on its own.'),
  ('What if the holder is a UK business?', 'An active business with its own claim to the word usually keeps the handle.')],
 ['Small businesses and shops.', 'Creators and freelancers.', 'Agencies serving Irish clients.'], area='Ireland')

u('instagram-username-claim-new-zealand', 'Instagram Username Claim in New Zealand',
 'Want an Instagram username in New Zealand?', 'Username claim in New Zealand',
 'New Zealand business or creator whose name is held on Instagram by someone else? What an NZBN entry and an IPONZ mark add, and what to send.',
 'A New Zealand business name and the handle you want do not always match. Here is how that plays out.',
 'In New Zealand, the name on your NZBN or Companies Office entry may differ from the name customers know, and someone else may hold the handle. An NZBN record shows the registered name and start date, and an IPONZ trademark protects it. Send these with a screenshot of the holder’s profile and we say whether a claim is realistic.',
 [('Start with your NZBN', 'The registered name and date show how long the name has been yours.'),
  ('IPONZ filings help', 'A registered mark carries more weight than a trading name.'),
  ('Look at the holder', 'An empty handle and a copycat are treated differently.')],
 [S('Records that matter here', ul(['An NZBN or Companies Office record with the date.', 'An IPONZ trademark registration or filing.', 'Invoices or listings that show the name in use.', 'The date the holder opened the account.']), RULES),
  S('How to start', ol(['Write down the handle you want and the one you use now.', 'Collect your NZBN record and any IPONZ details.', 'Screenshot the holder’s profile and latest post.', 'Send the three items and a line on why the name is yours.']))],
 [('Does a sole trader count?', 'A registered sole trader name is evidence of the name. A trademark adds more.'),
  ('Do you only work with New Zealand clients?', 'No. Unbanz works with clients worldwide.'),
  ('What if the holder is an Australian business?', 'An active, genuine owner with their own claim usually keeps the handle.')],
 ['Small businesses and trades.', 'Creators and consultants.', 'Agencies serving New Zealand clients.'], area='New Zealand')

